def compute(vars):
    v1 = vars["v1"]
    v2 = vars["v2"]
    average_revenue = (v1 + v2) / 2

    return {
        "value": average_revenue,
        "trace": {
            "values": [v1, v2],
            "count": 2,
            "output_meta": {
                "currency": "USD",
                "scale": "million",
                "unit": None
            }
        }
    }
